import type { ValueStepperProps } from "./value-stepper.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import { InputClasses } from "@components/input";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "ValueStepper";

// Generate child element class names for the component, should match available style slots
export const ValueStepperClasses = {
  root: "exp-textura_value-stepper",
  sm: "exp-textura_value-stepper_sm",
  decrement: "exp-textura_value-stepper_decrement",
  increment: "exp-textura_value-stepper_increment",
  input: "exp-textura_value-stepper_input",
  inputSm: "exp-textura_value-stepper_input_sm",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  inline: {
    root: {
      borderColor: theme.inputValueStepper.inline.color.border.enabled,
      color: theme.inputValueStepper.inline.color.content.enabled,
    },
    hover: {
      borderColor: theme.inputValueStepper.inline.color.border.hover,
      color: theme.inputValueStepper.inline.color.content.hover,
    },
    pressed: {
      borderColor: theme.inputValueStepper.inline.color.border.pressed,
      color: theme.inputValueStepper.inline.color.content.pressed,
    },
    focus: {
      borderColor: theme.inputValueStepper.inline.color.border.pressed,
      color: theme.inputValueStepper.inline.color.content.pressed,
    },
    input: {
      borderRadius: theme.inputValueStepper.inline.border.radius,
      color: theme.inputValueStepper.inline.color.content.enabled,
    },
    inputHover: {
      backgroundColor: theme.color.background.defaultHover,
    },
    inputPressed: {
      backgroundColor: theme.color.background.defaultPressed,
    },
  },
});

const generateStyles = (props: ValueStepperProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<ValueStepperProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),

    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "inline-flex",
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
    backgroundColor: theme.inputValueStepper.default.color.background.enabled,
    borderRadius: theme.inputValueStepper.default.border.radius,
    border: `${theme.toRem(theme.inputValueStepper.default.border.width)} solid ${theme.inputValueStepper.default.color.border.enabled}`,
    color: theme.inputValueStepper.default.color.content.enabled,
    fontFamily: theme.typography.fontFamily.plusJakartaSans,
    height: theme.toRem(32),
    padding: `0 ${theme.toRem(theme.spacing[4])}`,
    width: theme.toRem(102),

    "&:hover": {
      borderColor: theme.inputValueStepper.default.color.border.hover,
      color: theme.inputValueStepper.default.color.content.hover,
      ...styleSlots?.hover,
    },

    "&:active": {
      borderColor: theme.inputValueStepper.default.color.border.pressed,
      color: theme.inputValueStepper.default.color.content.pressed,
      ...styleSlots?.pressed,
    },

    "&:focus-within": {
      borderColor: theme.inputValueStepper.default.color.border.pressed,
      color: theme.inputValueStepper.default.color.content.pressed,
      ...styleSlots?.focus,
    },

    [`.${ValueStepperClasses.decrement}, .${ValueStepperClasses.increment}`]: {
      width: theme.toRem(24),
      height: theme.toRem(24),
      border: "none",
      backgroundColor: "transparent",
      color: "inherit",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      cursor: "pointer",

      "& svg": {
        width: theme.toRem(16),
        height: theme.toRem(16),
      },
    },

    [`.${ValueStepperClasses.decrement}`]: {
      "&:hover": {
        ...styleSlots?.decrementHover,
      },
      "&:active": {
        ...styleSlots?.decrementActive,
      },
      "&:disabled": {
        ...styleSlots?.decrementDisabled,
      },
      "& svg": {
        ...styleSlots?.decrementIcon,
      },
      marginInlineEnd: theme.toRem(theme.spacing[4]),
      ...styleSlots?.decrement,
    },

    [`.${ValueStepperClasses.increment}`]: {
      "&:hover": {
        ...styleSlots?.incrementHover,
      },
      "&:active": {
        ...styleSlots?.incrementActive,
      },
      "&:disabled": {
        ...styleSlots?.incrementDisabled,
      },
      "& svg": {
        ...styleSlots?.incrementIcon,
      },
      marginInlineStart: theme.toRem(theme.spacing[4]),
      ...styleSlots?.increment,
    },

    [`.${ValueStepperClasses.input}`]: {
      flex: 1,
      height: "100%",
      minWidth: theme.toRem(32),
      border: "none",
      backgroundColor: "transparent",
      borderRadius: theme.inputValueStepper.default.border.radius,
      margin: 0,
      overflow: "hidden",

      [`.${InputClasses.root}`]: {
        height: "100%",
      },

      // Override internal Input styles
      [`.${InputClasses.input}`]: {
        textAlign: "center",
        padding: "0",
        height: "100%",
        width: "fill-available",
        ...theme.typography.body.md,

        // Suppress native spin buttons
        "&::-webkit-outer-spin-button, &::-webkit-inner-spin-button": {
          "-webkit-appearance": "none",
          margin: 0,
        },

        "&[type=number]": {
          "-moz-appearance": "textfield",
        },

        // Ensure no focus outline on the input itself
        "&:focus-visible": {
          outline: "none !important",
          boxShadow: "none !important",
          ...styleSlots?.inputFocus,
        },

        "&:hover": {
          ...styleSlots?.inputHover,
        },

        "&:active": {
          ...styleSlots?.inputPressed,
        },

        ...styleSlots?.input,
      },

      [`.${InputClasses.inputWrapper}`]: {
        border: "none",
        boxShadow: "none",
        backgroundColor: "transparent",
        height: "100%",
        padding: 0,
        borderWidth: 0,
        minWidth: "unset",

        // Remove any hover/active states from the inner input wrapper
        "&:hover, &:active, &[data-focus='true'], &[data-active='true'], &[data-disabled='true']": {
          border: "none",
          boxShadow: "none",
          backgroundColor: "transparent",
          outline: "none",
          borderWidth: 0,
        },
      },

      ...styleSlots?.input,
    },

    // Small size overrides
    [`&.${ValueStepperClasses.sm}`]: {
      height: theme.toRem(24),
      margin: 0,
      padding: 0,
      width: theme.toRem(84),

      [`.${ValueStepperClasses.input}`]: {
        [`.${InputClasses.sm}`]: {
          [`.${InputClasses.inputWrapper}`]: {
            height: "100%",
          },
          ...theme.typography.body.sm,
          ...styleSlots?.inputSm,
        },
      },

      ...styleSlots?.sm,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledValueStepper = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<ValueStepperProps>((props) => generateStyles(props));
